public static List<PathSegmentImpl> decodePath(URI u, boolean decode) {
    List<PathSegmentImpl> result = new ArrayList<>();
    String path = u.getPath();
    if (path == null || path.isEmpty()) {
        return result;
    }
    String[] parts = path.split("/");
    int start = 0;
    if (path.startsWith("/")) {
        start = 1; // skip leading empty
    }
    for (int i = start; i < parts.length; i++) {
        String seg = parts[i];
        String decoded = seg;
        if (decode) {
            try {
                decoded = URLDecoder.decode(seg, StandardCharsets.UTF_8.name());
            } catch (UnsupportedEncodingException e) {
                decoded = seg;
            }
        }
        result.add(new PathSegmentImpl(seg, decoded));
    }
    return result;
}

